def statement(lines, release):
    credits = ASSIGN_CREDITS_BY_RELEASE[release](lines)
    response_lines = [
        {
            "line_id": line["line_id"],
            "credit_cents": credits[line["line_id"]],
            "amount_due_cents": line["charge_cents"] - credits[line["line_id"]],
        }
        for line in lines
    ]
    return {
        "release": release,
        "credit_cents": sum(credits.values()),
        "amount_due_cents": sum(l["amount_due_cents"] for l in response_lines),
        "lines": response_lines,
    }


def handle(request):
    command = request.get("command")
    if command == "ping":
        return {"status": "ok", "product": "Meridian Credits"}
    if command == "quote":
        return quote_line(request["line"], resolve_release(request))
    if command == "total":
        return total_statement(request["lines"], resolve_release(request))
    if command == "statement":
        return statement(request["lines"], resolve_release(request))
    return {"error": "unknown_command"}
